<?php require 'includes/config.php';$pageTitle='Wishlist';include 'includes/header.php';?><section class="page-hero"><div class="container"><span class="eyebrow">Saved products</span><h1>Your wishlist</h1><p>Wishlist items are stored in your browser for this academic demo.</p></div></section><section class="section"><div class="container"><div id="wishlist-grid" class="product-grid"></div><div id="wish-empty" class="empty-state"><h2>No saved items yet</h2><a class="btn" href="shop.php">Browse products</a></div></div></section><script>document.addEventListener('DOMContentLoaded',()=>{const a=JSON.parse(localStorage.getItem('wishlist')||'[]'),g=document.getElementById('wishlist-grid'),e=document.getElementById('wish-empty');if(a.length){e.style.display='none';g.innerHTML=a.map(p=>`<article class="product-card"><div class="product-media"><img src="${p.image}"></div><div class="product-body"><h3>${p.name}</h3><span class="price">LKR ${Number(p.price).toLocaleString()}</span><button class="add-btn" data-add='${JSON.stringify(p)}'>Add to cart</button></div></article>`).join('')}})</script><?php include 'includes/footer.php';?>
